(()=>{
const box=document.createElement('section');box.className='card pass';document.querySelector('#profiles').prepend(box);
let key='',rev=0,busy=false;try{[key,rev]=JSON.parse(localStorage.getItem('wrPassport')||'["",0]')}catch{}
function persist(){try{localStorage.setItem('wrPassport',JSON.stringify([key,rev]))}catch{}}
function render(msg=''){box.innerHTML='<details><summary>◈ &nbsp; بروفايل اللعب <small>'+(key?'مربوط':'بلا إيميل')+'</small></summary><p>'+(key?'حفظ نقطك من بعد كل حصة. احتافظ بالكود فبلاصة خاصة: اللي عندو الكود يقدر يدخل للبروفايل.':'بضغطة وحدة كتفتح بروفايل وكتحفظ فيه التقدم ديال هاد الجهاز.')+'</p>'+(key?'<button data-a="save" class="gold">حفظ تقدم هاد الجهاز</button><button data-a="read">استرجع آخر نسخة محفوظة</button><details><summary>الكود السرّي ديالي</summary><input aria-label="الكود السرّي" readonly dir=ltr><button data-a="copy">نسخ الكود</button></details>':'<button data-a="new" class="gold">إنشاء بروفايل بضغطة</button><details><summary>عندي كود من جهاز آخر</summary><form><label>الكود السرّي<input dir=ltr required autocomplete=off autocapitalize=none enterkeyhint=go></label><button>فتح البروفايل</button></form></details>')+'<output aria-live="polite"></output></details>';box.querySelector('output').textContent=msg;if(key)box.querySelector('input').value=key.match(/.{4}/g).join('-');if(msg)box.firstChild.open=true}
async function rpc(code,snapshot=null,expected=null){let r=await fetch('https://newlviixdgxlkffpsmua.supabase.co/rest/v1/rpc/wortreise_passport',{method:'POST',headers:{apikey:'sb_publishable_QTIc_1dUyhDVoJQpzxMb5Q_-nkAjepR','Content-Type':'application/json'},body:JSON.stringify({code,snapshot,expected})});if(!r.ok)throw Error('ما قدرناش نتاصلو بالخدمة. عاود المحاولة.');return r.json()}
async function act(a){if(busy)return;busy=true;let out=box.querySelector('output');try{if(a==='copy'){await navigator.clipboard.writeText(key);out.textContent='تنسخ الكود.';return}
if(a==='new'){let k=Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');let v=await rpc(k,st,0);if(!v)throw Error('عاود المحاولة');key=k;rev=v.revision;persist();render('تخلق البروفايل وتحفظ تقدمك. فتح «الكود السرّي ديالي» واحتافظ به.');return}
if(a==='save'){let v=await rpc(key,st,rev);if(!v)throw Error('النسخة تبدلات من جهاز آخر. استرجعها قبل الحفظ.');rev=v.revision;persist();render('تحفظ التقدم ✓');return}
let k=a==='enter'?box.querySelector('input').value.toLowerCase().replace(/[\s-]/g,''):key;if(!/^[a-f0-9]{32}$/.test(k))throw Error('لسق الكود كامل.');let v=await rpc(k);if(!v)throw Error('ما لقيناش هاد الكود. تأكد منو.');if(!confirm('تعوض التقدم فهاد الجهاز بالنسخة المحفوظة؟'))return;key=k;rev=v.revision;persist();st=v.progress;home();render('رجع التقدم ديالك ✓')}catch(e){out.textContent=e instanceof TypeError?'تعذّر الاتصال. التقدم المحلي باقي محفوظ.':e.message}finally{busy=false}}
box.onclick=e=>{let b=e.target.closest('[data-a]');if(b)act(b.dataset.a)};box.onsubmit=e=>{e.preventDefault();document.activeElement.blur();act('enter')};render()
})();
